/**
 * @description End-to-end tests for publishing and sending outbound transactions (with data). The payload logic is tested
 * without data in IntegrationHubPayloadTest. Records that lead to a callout are created after Test.startTest: a callout
 * in a job that runs at stopTest fails if DML came before startTest.
 */
@IsTest
private class IntegrationHubOutboundTest {

    @TestSetup
    static void setup() {
        IntegrationHubTestData.setupAll();
    }

    @IsTest
    static void publishSendsSelectedFieldsAndSucceeds() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(200, '{"reference":"R-1"}'));
            Test.startTest();
            List<Id> ids = IntegrationHub.publish(IntegrationHubTestData.OUT_KEY, IntegrationHubTestData.accounts());
            Test.stopTest();
            Assert.areEqual(2, ids.size(), 'one transaction per record');
            IH_Transaction__c t = IntegrationHubTestData.transactions(IntegrationHubTestData.OUT_KEY)[0];
            Assert.areEqual('Success', t.Status__c, 'a 2xx reply is Success: ' + t.Error_Message__c);
            Assert.areEqual('R-1', t.External_Reference_Id__c, 'the reference is read from the reply');
            Assert.areEqual('HANDLED', t.Correlation_Id__c, 'the response handler ran');
            Assert.isTrue(t.Request_Payload__c.contains('"sfTransactionId"'), 'the body carries the transaction Id');
            Assert.isTrue(t.Request_Payload__c.contains('"Owner.Name"'), 'parent fields are sent');
            Assert.isNotNull(t.Completed_At__c, 'Completed At is set');
            Assert.isNull(t.Business_Status__c, 'without Business Data In Response the handler runs inline as before');
            Assert.isTrue(t.Request_Url__c.startsWith('POST callout:IH_Test/records/'), 'the method and endpoint are kept');
        }
    }

    @IsTest
    static void longAnswerIsKeptInAFile() {
        System.runAs(IntegrationHubTestData.admin()) {
            String answer = '{"reference":"BIG","pad":"' + 'z'.repeat(140000) + '"}';
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(200, answer));
            Test.startTest();
            IntegrationHub.publish(IntegrationHubTestData.OUT_KEY, new List<SObject>{ IntegrationHubTestData.accounts()[0] });
            Test.stopTest();
            IH_Transaction__c t = IntegrationHubTestData.transactions(IntegrationHubTestData.OUT_KEY)[0];
            Assert.areEqual(131072, t.Response_Body__c.length(), 'the field keeps the first part');
            Assert.isNotNull(IntegrationHubBodyFiles.fileIds(t.Id).get(IntegrationHubBodyFiles.RESPONSE_PREFIX), 'the full answer is a File');
            Assert.areEqual(answer, IntegrationHubBodyFiles.fullBody(t.Id, IntegrationHubBodyFiles.RESPONSE_PREFIX, t.Response_Body__c),
                'the full answer can be read back');
            IH_Attempt__c attempt = (IH_Attempt__c) IntegrationHubData.queryFirst(
                'SELECT Kind__c, Response_Body__c FROM IH_Attempt__c WHERE Transaction__c = :id LIMIT 1', new Map<String, Object>{ 'id' => t.Id });
            Assert.areEqual('Send', attempt.Kind__c, 'a send is logged as Send');
            Assert.areEqual(131072, attempt.Response_Body__c.length(), 'the attempt keeps the answer, cut to the field');
        }
    }

    @IsTest
    static void apexClassBuildsThePayload() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(200, '{}'));
            Test.startTest();
            IntegrationHubTestData.newApexClassEvent(IntegrationHubTestData.CLASS_KEY);
            IntegrationHub.publish(IntegrationHubTestData.CLASS_KEY, IntegrationHubTestData.accounts());
            Test.stopTest();
            Map<String, IH_Transaction__c> byKind = new Map<String, IH_Transaction__c>();
            for (IH_Transaction__c t : IntegrationHubTestData.transactions(IntegrationHubTestData.CLASS_KEY)) {
                Assert.areEqual('Success', t.Status__c, 'both bodies are sent: ' + t.Error_Message__c);
                byKind.put(t.Request_Payload__c.contains('"map"') ? 'map' : 'string', t);
            }
            IH_Transaction__c mapTxn = byKind.get('map');
            Assert.isNotNull(mapTxn, 'one record got the Map body');
            Map<String, Object> sent = (Map<String, Object>) JSON.deserializeUntyped(mapTxn.Request_Payload__c);
            Assert.areEqual(String.valueOf(mapTxn.Id), sent.get('sfTransactionId'), 'the transaction Id is added to a Map body');
            Assert.areEqual(2, sent.get('batch'), 'the class is called once with every record of the batch');
            Assert.areEqual('{"kind":"string"}', byKind.get('string').Request_Payload__c, 'a String body is sent as it is');
        }
    }

    @IsTest
    static void manualRetrySendsAgain() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(200, '{"id":"X-9"}'));
            Test.startTest();
            IH_Transaction__c t = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Failed');
            IntegrationHubData.updateAll(new List<IH_Transaction__c>{
                new IH_Transaction__c(Id = t.Id, Status__c = 'Retry', Retry_Count__c = 0, Rebuild_Payload__c = true, Error_Message__c = null) });
            Test.stopTest();
            IH_Transaction__c after = IntegrationHubTestData.transactions(IntegrationHubTestData.OUT_KEY)[0];
            Assert.areEqual('Success', after.Status__c, 'a manual retry is sent at once: ' + after.Error_Message__c);
            Assert.areEqual('X-9', after.External_Reference_Id__c, 'id is used as the reference');
            Assert.isTrue(after.Request_Payload__c.contains('"fields"'), 'the payload was rebuilt');
            List<IH_Attempt__c> attempts = (List<IH_Attempt__c>) IntegrationHubData.query(
                'SELECT Outcome__c, Payload_Used__c, Http_Status_Code__c FROM IH_Attempt__c WHERE Transaction__c = :id',
                new Map<String, Object>{ 'id' => t.Id });
            Assert.areEqual(1, attempts.size(), 'each send is logged as one Integration Attempt');
            Assert.areEqual('Success', attempts[0].Outcome__c, 'the attempt keeps the outcome');
            Assert.areEqual('New', attempts[0].Payload_Used__c, 'the payload was built for this send');
            Assert.areEqual(200, attempts[0].Http_Status_Code__c, 'the attempt keeps the HTTP status');
        }
    }

    @IsTest
    static void longPayloadIsSentAndStoredCut() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(200, '{}'));
            Test.startTest();
            IntegrationHubTestData.newApexClassEvent(IntegrationHubTestData.LONG_KEY);
            IntegrationHub.publish(IntegrationHubTestData.LONG_KEY, new List<SObject>{ IntegrationHubTestData.accounts()[0] });
            Test.stopTest();
            IH_Transaction__c t = IntegrationHubTestData.transactions(IntegrationHubTestData.LONG_KEY)[0];
            Assert.areEqual('Success', t.Status__c, 'a payload longer than the field is still sent: ' + t.Error_Message__c);
            Assert.areEqual(131072, t.Request_Payload__c.length(), 'the stored copy fits the field exactly');
            Assert.isTrue(t.Request_Payload__c.contains('characters; the full payload was sent'), 'the stored copy is marked as cut');
        }
    }

    @IsTest
    static void publishIsNullSafe() {
        System.runAs(IntegrationHubTestData.admin()) {
            List<IH_Connection__c> accounts = IntegrationHubTestData.accounts();
            Assert.areEqual(0, IntegrationHub.publish(null, accounts).size(), 'no event key: nothing');
            Assert.areEqual(0, IntegrationHub.publish(IntegrationHubTestData.OUT_KEY, (List<SObject>) null).size(), 'null list: nothing');
            Assert.areEqual(0, IntegrationHub.publish(IntegrationHubTestData.OUT_KEY, new List<SObject>{ null, new Account() }).size(),
                'null records and records without Id are skipped');
            Assert.areEqual(0, IntegrationHub.publish('NO_SUCH_EVENT', accounts).size(), 'unknown event: nothing');
            Assert.areEqual(0, IntegrationHub.publish(IntegrationHubTestData.IN_KEY, accounts).size(), 'inbound event: nothing');
            IntegrationHubData.insertAll(new List<IH_Settings__c>{
                new IH_Settings__c(SetupOwnerId = UserInfo.getOrganizationId(), Disable_Publishing__c = true) });
            Assert.areEqual(0, IntegrationHub.publish(IntegrationHubTestData.OUT_KEY, accounts).size(), 'publishing disabled: nothing');
        }
    }

    @IsTest
    static void noJobCapacityMarksFailed() {
        System.runAs(IntegrationHubTestData.admin()) {
            IntegrationHubSender.forceNoCapacity = true;
            List<Id> ids = IntegrationHub.publish(IntegrationHubTestData.OUT_KEY, IntegrationHubTestData.accounts());
            Assert.areEqual(2, ids.size(), 'the transactions are still created');
            for (IH_Transaction__c t : IntegrationHubTestData.transactions(IntegrationHubTestData.OUT_KEY)) {
                Assert.areEqual('Failed', t.Status__c, 'nothing waits forever when no job can be queued');
                Assert.isTrue(t.Error_Message__c.contains('too many background jobs'), 'the reason is given');
            }
        }
    }

    @IsTest
    static void recoveryMarksStuckTransactionsFailed() {
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Transaction__c t = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Pending');
            IntegrationHubSender.Recovery recovery = new IntegrationHubSender.Recovery(new List<Id>{ t.Id });
            recovery.execute(new IntegrationHubTestData.StubFinalizerContext(ParentJobResult.SUCCESS));
            Assert.areEqual('Pending', IntegrationHubTestData.transactions(IntegrationHubTestData.OUT_KEY)[0].Status__c,
                'a successful job changes nothing');
            recovery.execute(new IntegrationHubTestData.StubFinalizerContext(ParentJobResult.UNHANDLED_EXCEPTION));
            IH_Transaction__c after = IntegrationHubTestData.transactions(IntegrationHubTestData.OUT_KEY)[0];
            Assert.areEqual('Failed', after.Status__c, 'a dead job marks its transactions Failed');
            Assert.isTrue(after.Error_Message__c.contains('Job died'), 'the reason is kept');
        }
    }
}
